#include "stdafx.h"

// =============================================================================
//  (th4) SWAHILI localization (LANG_SW = 19). Mirrors LocalizationIT.cpp / -ES.
//
//  ENCODING: PURE ASCII. Standard Kiswahili (Kiswahili sanifu) orthography uses
//  the plain Latin alphabet with NO diacritics at all -- not one accent, cedilla
//  or macron. So there is nothing to fold, no .mor to mount, no font frame to
//  read and no codepage of its own. SW rides the ES/IT ASCII-fold case in
//  Localization.cpp purely as a SAFETY NET: if a stray accented byte ever gets
//  pasted into this file it folds to its base letter instead of drawing blank.
//  Because the file is ASCII, the C2022 greedy-hex trap that bites RU/PT/FR/PL
//  cannot occur here, and the meta-menu atlas (which has no accented glyphs)
//  renders SW_Menu directly -- which is why SW joins the LMenu is() lists in
//  Hell.cpp rather than needing an inline-byte branch of its own.
//
//  REGISTER: native-coinage-first, as Ibragim asked. Where Swahili has its own
//  word it is used in preference to an English loan: deraya (armour), uharibifu
//  (damage), ukinzani (resistance), zimwi/mazimwi (monster), mamluki
//  (mercenary), gombo (scroll), tundu (socket), kito (gem), madhabahu (shrine),
//  ghala (stash), mzigo (inventory), kipaji (perk), tabia (trait), jukumu
//  (quest). Only genuinely untranslatable terms stay: "mana" (no Swahili
//  equivalent exists) and proper nouns (Tristram, Diablo, Horazon, Oni, Kensei).
//
//  GLOSSARY LOCKS (keep these consistent if you extend the file):
//    life = uhai        strength = nguvu      magic  = uchawi
//    mana = mana        dexterity = ustadi    vitality = uzima
//    damage = uharibifu accuracy = usahihi    level  = ngazi
//    armor = deraya     resistance = ukinzani spell  = tamko (pl. matamko)
//    Undead = Wafu Hai  Demons = Mashetani    Beasts = Wanyama
//
//  ---- STATUS -------------------------------------------------------------
//  BATCHES 1-2. FILLED: Ui (1162), Menu (200), Element, Spicies, Quest (41),
//  OnScreen (113), plus SW_TraitName / SW_TraitBenefit / SW_TraitPenalty (112
//  each) and SW_GCInfoName / SW_GCInfoDesc (30 each).
//  Speech is COMPLETE (464 rows). IceAge (154), Spell (77), SpellNom (77) and
//  Warp (164) are COMPLETE too.
//  PerkName (299) and PerkDesc (312) are COMPLETE too.
//  AffixPrefix (322) and AffixSuffix (381) are COMPLETE too.
//  BaseName2 (231), SW_MonsterName (420) and SW_UniqueMonsterName (954) are
//  COMPLETE too.
//  BaseItem (2261) is COMPLETE too.
//  UniqueItem (2957) is COMPLETE too -- ALL 16 string tables and all three index
//  tables are now filled.
//  Those, plus SW_MonsterName / SW_UniqueMonsterName
//  and the Hell.cpp inline class-description dialogs, are the next batches. This
//  is a valid shippable state: language 19 gives a working build where anything
//  not yet translated reads as English.
//
//  Keys must match the English source literal BYTE-EXACTLY or the row is
//  silently ignored. Every key in this file was taken from the UNION of all
//  shipped localizations (never from ES alone -- ES has known gaps), and every
//  row was machine-checked for printf-specifier parity against its key before
//  being emitted.
// =============================================================================

struct UiStr  { const char* en; const char* sw; }; // .sw column holds the SW text
struct IdxStr { int index; const char* sw; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	// (th4) OVL_WARP_OBL must be present so this enum stays aligned with the master
	// one in Localization.cpp. SW registers no table for it (see SW_Warp).
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// -----------------------------------------------------------------------------
//  A lone { 0, 0 } placeholder => count 0 => English fallback.
// -----------------------------------------------------------------------------

// (th4) Main UI table. COMPLETE: 1162 rows -- the union of every shipped loc's
// key set. The *_one / *_few / *_many keys are PLURAL FORMS; Swahili nouns do
// not inflect for number the way Russian does (the class prefix carries it), so
// _few and _many hold the same word. Many rows are LINE FRAGMENTS the tooltip
// stacks into one sentence: they keep their own line breaks and are kept short
// enough for the panel width. The stat-column abbreviations (ngv/ust/uch/uzm,
// kinz. mapigo) are deliberately short for the same reason. %c pairs are colour
// -control bytes wrapping a number: their order and count are preserved exactly
// and the Swahili is shaped around them. Class names here are checked against
// SW_Menu -- the character sheet and the creation menu must show the same word.
