// (th4) Unique (named artefact) item names. COMPLETE: 2957 rows, all DISTINCT.
// GENERATED from the shared head/modifier vocabulary (the same one SW_BaseItem uses),
// extended for this table by 731 more head nouns, 499 modifiers and 535 "of"-tails.
// Four name shapes, handled separately:
//   * "<Owner>'s <Thing>" (355)  -> "<Thing> <concord> <Owner>". The OWNER is always
//     kept verbatim -- mostly invented names, but a few are ordinary English nouns
//     ("Scholar's", "Hell's") and those stay English too, since nothing in the data
//     tells them apart and half-translating a name is worse than leaving it.
//   * "<Thing> of <X>" (774)     -> "<Thing> <concord> <X>". This maps onto the
//     Swahili genitive exactly: "Rod of Infernal Flames" -> "Fimbo ya Miali ya
//     Jehanamu". An article in the tail ("the Fallen") simply drops.
//   * single-word names (740) were SPLIT on a later audit (Ibragim spotted "Velocity"
//     and "Bladebuckle" sitting in English): 628 of them are TRANSPARENT English
//     compounds and ARE translated -- Bladebuckle -> "Kifungo cha Bapa", Velocity ->
//     "Mwendo wa Kasi", Bonebreaker -> "Mvunja Mifupa". Only 112 remain verbatim, and
//     those are genuinely FOREIGN or invented proper nouns that read as foreign in the
//     English too: Latin (Invictus, Sanguinarius, Exterminatus), German (Gotterzorn,
//     Weltenbrecher), Japanese (Bankai, Kusanagi, Shirotachi), astronomy (Betelgeuse,
//     Polaris), gladiator classes (Secutor, Thraex, Murmillo -- matching SW_Ui), music
//     terms (Legato, Nocturne, Forte) and pure coinages (Amurdill, Arvakar, Borz).
//     NOTE the earlier, wrong policy was "keep every single-word name", copied from
//     SW_UniqueMonsterName. It is right THERE (those really are boss names) and wrong
//     HERE (these are item names built from ordinary English words). Do not re-unify.
//   * "<Mods> <Head>" (1087)     -> head + concord + modifiers reversed.
//   * plus exactly ONE key that is both: "Tal-Rasha's Path of Torment".
//
// LEADING "The" IS DROPPED -- Swahili has no article -- EXCEPT where dropping it would
// collide with a real key that differs only by that word. Three such pairs exist
// ("Celestial Star"/"The Celestial Star", "Undead Crown"/"The Undead Crown",
// "Eater of Souls"/"The Eater of Souls"), so those keep it. Do not "tidy" this away.
//
// Latin and invented words in the vocabulary (Bellatoris, Invicta, Vitae, Custodia,
// Nox, Mortis...) are kept verbatim: they are foreign words in the English too.
