// (th4) Affix prefixes. COMPLETE: 322 rows, all values DISTINCT.
// The 322 keys were verified to exist in the English affix sources -- the six
// Affixes*.cpp files TOGETHER (Affixes / AffixesClassic / AffixesColiseum /
// AffixesEnchant / AffixesRare / AffixesSigil), not Affixes.cpp alone, which holds
// only 242 of them. Nine shipped locs carry 314 rows and eight carry 322; 322 is the
// correct, fully-covered set (0 keys absent from source).
// WORD ORDER, a known and accepted limitation: the engine builds "PREFIX Base SUFFIX",
// but Swahili puts qualifiers AFTER the noun. These are therefore bare forms that read
// as a compound in prefix position ("Chuma Upanga"), exactly the trade ES/PT/ID make
// -- see the gender-agreement note above ES_AffixPrefix. Changing it would need an
// engine change to the name builder, not a table change.
