// Rendered through the SW_Ui row "%s of %s" -> "%s ya %s", so these are BARE NOUNS
// with no connector of their own; the "the " in keys like "the Bat" is an English
// article Swahili does not have and is simply dropped ("Popo"). Case parity still
// applies and is checked after stripping that "the ": "the Bat" -> "Popo" but
// "the bat" -> "popo".
