// (th4) Base item names. COMPLETE: 2261 rows, all values DISTINCT.
// GENERATED COMPOSITIONALLY, not written line by line, from three vocabularies:
// 349 head nouns (each carrying its Swahili NOUN-CLASS CONCORD), 718 modifier words
// and 65 "of"-tails. That is what makes the word order right: English builds
// "Modifier Head", Swahili builds "Head + concord + modifiers in REVERSE order", so
// "Boiled Leather Gloves" -> "Glavu za Ngozi ya Kuchemshwa" and "Barbaric Sword" ->
// "Upanga wa Kishenzi". Concord varies by class and is stored per head: Upanga (cl.11)
// takes wa, Ngao (cl.9) ya, Shoka (cl.5) la, Kitabu (cl.7) cha, Viatu (cl.8) vya.
//
// PARSE ORDER MATTERS -- get it wrong and the heads come out as junk like "1)" or "IV":
//   1. strip the trailing parenthetical  (grade 1)..(grade X), (Gen 2), (burst: 3),
//      (burst: 7-9), (opens Abyss)  -- and re-append it VERBATIM at the end;
//   2. strip a trailing ROMAN NUMERAL (I..XXV, e.g. "Explosive Acid Flasks IV") and
//      re-append it verbatim too;
//   3. split an "of"-phrase, whose head is the word BEFORE "of" ("Book of Fire Wall");
//   4. only then is the head the last remaining word.
