// -----------------------------------------------------------------------------
//  Table access. A lone placeholder row reports 0 rows, so an unfilled table is
//  indistinguishable from an absent one and the English text is used.
// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr& r )  { return r.en == 0 && r.sw == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index == 0 && r.sw == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* SW_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(SW_Ui);           return SW_Ui;
		case OVL_MENU:          *n = countRows(SW_Menu);         return SW_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(SW_UniqueItem);   return SW_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(SW_AffixPrefix);  return SW_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(SW_AffixSuffix);  return SW_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(SW_BaseItem);     return SW_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(SW_BaseName2);    return SW_BaseName2;
		case OVL_ELEMENT:       *n = countRows(SW_Element);      return SW_Element;
		case OVL_SPICIES:       *n = countRows(SW_Spicies);      return SW_Spicies;
		case OVL_ICEAGE:        *n = countRows(SW_IceAge);       return SW_IceAge;
		case OVL_SPELL:         *n = countRows(SW_Spell);        return SW_Spell;
		case OVL_SPELL_NOM:     *n = countRows(SW_SpellNom);     return SW_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(SW_PerkName);     return SW_PerkName;
		case OVL_PERK_DESC:     *n = countRows(SW_PerkDesc);     return SW_PerkDesc;
		case OVL_WARP:          *n = countRows(SW_Warp);         return SW_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* SW_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(SW_Speech);     return SW_Speech;
		case OVL_ONSCREEN:  *n = countRows(SW_OnScreen);   return SW_OnScreen;
		case OVL_QUEST:     *n = countRows(SW_Quest);      return SW_Quest;
	}
	*n = 0; return 0;
}

// -----------------------------------------------------------------------------
//  (th4) Dedicated per-language functions, reached through the dispatchers in
//  Localization.cpp (LocalizedTraitName / ...Benefit / ...Penalty and
//  LocalizedGCInfoName / ...Desc). Returning nullptr for an unknown id is the
//  normal "no translation" answer -- the caller falls back to English.
//
//  Trait wording is shared with SW_Menu ("Chagua Tabia" / "Faida" / "Hasara")
//  and with SW_Ui, so the creation menu and the character panel never show two
//  different Swahili words for one idea. All 112 trait names are DISTINCT --
//  checked mechanically, because the Select-Trait list is keyed by name.
//
//  GCInfoName/Desc feed the IN-GAME Game Changers panel (InfoWindow.cpp), which
//  is a DIFFERENT surface from the creation-menu descriptions in SW_Menu: this
//  one is drawn by DrawLevelInfoText with the in-game CEL font and carries the
//  "name / blank / category / blank / body" layout. The two texts are kept
//  consistent in wording but are not the same strings.
//
//  NOTE on GrimDeal: the English penalty writes "%life, %mana". Swahili uses
//  "% uhai, % mana" WITH A SPACE on purpose -- "%uhai" would read as a printf
//  %u conversion if the string ever reached a formatter.
// -----------------------------------------------------------------------------

