const char* SW_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Hakuna (imerukwa)";
		case 1: return "Kuhifadhi kiotomatiki\n\n\nHubadilisha mtindo wa mchezo\n\nHuondoa haja ya mchezaji kuhifadhi mchezo mwenyewe; huhifadhiwa kiotomatiki, kama katika hali ya wachezaji wengi.";
		case 2: return "Vifaa Vilivyofungwa\n\n\nHuongeza changamoto\n\nHufanya isiwezekane kuvaa au kuvua vitu ukiwa vitani (isipokuwa nafasi za mikono).";
		case 3: return "Kuangusha Vitu\n\n\nHuongeza changamoto\n\nUkifa huangusha vitu ulivyovaa.\n\nOnyo: vitu vilivyoangushwa visipochukuliwa katika kipindi kilekile cha mchezo, vitatoweka.";
		case 4: return "Bila Jitihada\n\n\nHurahisisha mchezo\n\nMazimwi hukufanyia nusu ya uharibifu tu.\nHakuna urahisi zaidi ya huu.";
		case 5: return "Ishi kwa Ardhi\n\n\nHuongeza changamoto\n\nWenyeji hawatakuuzia kitu chochote.\n\nLakini hawataacha kutoa huduma zao: maongezi, mazungumzo ya majukumu, kutengeneza, kutambua, kuroga, ufundi, matundu, kujaza chaji.";
		case 6: return "Isiyowezekana\n\n\nHufanya mchezo kuwa mgumu\n\nMazimwi hukufanyia uharibifu mara mbili.\nHakuna ugumu zaidi ya huu.";
		case 7: return "Marufuku\n\n\nHuongeza changamoto\n\nMazimwi hayataangusha tena viboreshaji vya sifa kwa nasibu\nKumbuka: kipaji cha Mnywaji Mkubwa bado kitatoa viboreshaji kutoka kwa mazimwi ya kipekee";
		case 8: return "Mgusano Kamili\n\n\nHurahisisha mchezo\n\nMazimwi yenye mashambulizi ya mbali hayarudi nyuma.";
		case 9: return "Ndugu wa Usiku\n\n\nHukufanya mnyonya damu\n\nUnaishi na kufa kwa damu. Njaa yako haitosheki, lakini una kila nyenzo ya kuwinda wanyonge\n\nHii hubadilisha mchezo.\nHutumii vitu na hutegemea nguvu zako za asili.";
		case 10: return "Kata na Chana\n\n\nHurahisisha mchezo\n\nHuhitaji tena kubadili aina ya silaha (kali au butu) kulingana na aina ya zimwi. Silaha zote hufanya uharibifu wa kawaida kwa aina zote za mazimwi.";
		case 11: return "Aliyechanjwa\n\n\nHurahisisha mchezo\n\nMazimwi hupoteza kinga zote, na hakuna haja ya kubadili matamko - kila aina ya tamko hufanya kazi.\nLaana ya Jiwe, Roho ya Mifupa, matamko ya asili na matakatifu hayaguswi.";
		case 12: return "Hiyo Ni Siri Yangu\n\n\nHurahisisha mchezo\n\nGhadhabu haina mapumziko na yaweza kutamkwa upya mara tu inapoisha.";
		case 13: return "Hakuna Kupona\n\n\nHuongeza changamoto\n\nShujaa hana kupona kwa msingi kwa uhai wala mana.";
		case 14: return "Mikono Safi\n\n\nHuongeza changamoto\n\nMazimwi hayaangushi vitu vinavyoweza kuvaliwa na shujaa.\nMchezaji anatakiwa kuvipata kwa kununua na/au kuroga.";
		case 15: return "Zama za Barafu\n\n\nMabadiliko ya sura\n\nNgazi za handaki huonekana kama ni kipupwe kikuu; kila kitu kimeganda na kufunikwa barafu.\nUmewahi kuwaza jehanamu ingeonekanaje ikiganda?";
		case 16: return "Siku Ileile\n\n\nHubadilisha mtindo wa mchezo\n\nHandaki lilelile huundwa kila mara, likiwa na mazimwi yaleyale. Waweza kucheza na kuboresha muda wako kila unapocheza.";
		case 17: return "Mazimwi Magumu Zaidi\n\n\nHufanya mchezo kuwa mgumu\n\nMazimwi yana +200% ya uhai.";
		case 18: return "Vitu Visivyoharibika\n\n\nHurahisisha mchezo\n\nVitu havitaharibiwa uimara ukifika sifuri. Badala yake, vitu vitakuwa havitumiki hadi vitengenezwe.";
		case 19: return "Hakuna Ramani\n\n\nHuongeza changamoto\n\nRamani haipatikani\nItakubidi kutafuta njia yako handakini bila kuitegemea\n\nUmeshapotea?";
		case 20: return "Uharibifu Mara Mbili\n\n\nHurahisisha mchezo\n\nMashambulizi yako hufanya uharibifu mara mbili kwa mazimwi\n\nOnyo: waweza kuwa rahisi kupita kiasi.\nUsichague hii kama unataka kubaki na msisimko wa vita.";
		case 21: return "Usione Uovu\n\n\nHuongeza changamoto\n\nKuona hakuangazi mazimwi gizani.";
		case 22: return "Kifo Cheusi\n\n\nUmeambukizwa\n\nTauni ya Kifo Cheusi imekushika. Itakua polepole ikileta dalili mbaya ambazo hatimaye zitakuua bila shaka.\n\nHuwezi kuiponya, huwezi kuitibu, wala huwezi kuizuia. Kadiri muda unavyopita itazidi kuwa kali. Hakuna kuponyoka ugonjwa huu wa mauti.";
		case 23: return "Bahati Mbaya\n\n\nHuongeza changamoto\n\nBahati huisha mapema au baadaye. Yako haikuanza hata kidogo.\n\nAnza mchezo na sifa zote sawa na 5. Pata alama 2 tu za sifa kila ngazi. Ustadi wa kupata uchawi, uzoefu unaopatikana na uwezo wa kupata dhahabu vimepunguzwa kwa 75%. Anza mchezo bila kitu chochote.\n\nHakuna vipaji vya kukusaidia kwa uzoefu, kuangushiwa viboreshaji, kupata vitu vya uchawi wala sifa za ngazi.";
		case 24: return "Chuma Kikatili\n\n\nHuongeza changamoto\n\nMtu wa Chuma wa Diablo ya kiasili alikuwa tofauti.\n\nHakukuwa na nyongeza ya sifa kila ngazi, hakuna uzoefu wa ziada, hakuna mafuta wala utambuzi kutoka kwa mabwana. Wala hakuna nyongeza ya kupata uchawi.\n\nKigeuzi hiki kinakurudisha kwenye mizizi hiyo.";
		case 25: return "Kuongeza Kasi\n\n\nHurahisisha mchezo\n\nUzoefu umeongezwa mara 2.";
		case 26: return "Kujinyima\n\n\nHuongeza changamoto\n\nMchezo huhifadhiwa kiotomatiki.\n\nVitu huangushwa ukifa. Huwezi kufufuka mjini (lazima uanzishe mchezo mpya) na kwa sababu hiyo vitu vyote vilivyoangushwa hupotea.\n\nNi kama hali ya Kikatili, lakini badala ya kupoteza shujaa wako, unapoteza vitu ulivyovaa.";
		case 27: return "Terminator\n\n\nWewe ni kifaa cha mfululizo wa Cyberdyne Systems. Muundo 101, mpenyezaji. Hali ya kusoma-kuandika ya CPU imewashwa. Umetumwa zamani kutekeleza jukumu.\n\nLengo kuu: Uber Diablo.\n\nLengo la pili: kuangamiza mazimwi.\n\nSharti: onekana kama binadamu kwa wenyeji.\n\nNyongeza za msingi zimewekwa. Nyongeza za ziada zapatikana kwa kujifunza mwenyewe.";
		case 28: return "Mgeuko Mkuu\n\n\nUmbo lako laweza kubeba silaha zingemvunja mtu wa kawaida vipande viwili.\n\nBunduki ndogo.\n\nVitu visivyopaswa kuwepo duniani humu. Hutamki tena matamko. Huhitaji.\n\nUnapovuta kifyatuo, mlipuko hupasua vizazi vya jehanamu kama karatasi katika dhoruba.";
		case 29: return "Askari wa Enclave\n\n\nAskari wa Majeshi ya Enclave, aliyefunzwa kuangamiza wageuko na uchafu wa vinasaba.\n\nAmejikuta amekwama katika ulimwengu usiojua moto wa nyuklia, lakini wenye uchafu wa aina nyingine - vizazi vya jehanamu.\n\nAdui amebadilika. Kusudi halijabadilika.\n\nUwezo: Hutumia silaha za nishati na kupeleka ndege ndogo za vita. Ni bingwa wa mapigano ya asili.";
	}
	return nullptr;
}

// (th4) Base monster names, reached through LocalizedMonsterName() in
// Localization.cpp. COMPLETE: 420 cases covering 340 distinct English names -- the
// repeats are real (BaseMonsters[] has several "Risen Skeleton" / "Fallen One" /
// "Hell Clan" rows at different dungeon levels) and each repeat gets the SAME
// Swahili, so no two DIFFERENT English names share one Swahili value. That is the
// check that matters here and it is machine-verified.
// English source is the `name` field in BaseMonster.cpp (424 rows), not another loc.
// Wording is kept in step with tables already shipped: Stinger/Hellboar/Siegebreaker
// Beast/Goat Archer match SW_Spell's summon lines, Soul Hunter and Illusion Weaver
// match SW_IceAge, The Butcher matches SW_Quest, and the class-name monsters
